// Public WowCube game API: generated by tools/api/gen_api.py from the engine sources (api/SOURCE).
// Only what a game compiled as a cube module (OCT_APP_MODULE) uses. Do not edit: regenerate.
#pragma once
#include <stdint.h>
#include <stdbool.h>

//An app's version, as it sits in octPackHeader_t.AppVersion (oct_pack_format.h) and reaches the phone in
//octHostCatalogEntry_t.AppVersion. Four bytes, three of which are the version:
//
//      byte 3           byte 2   byte 1   byte 0
//      scheme           major    minor    patch
//
//      scheme 1 (OCT_APP_VERSION_SEMVER) -- bytes 2..0 are major.minor.patch, each 0..255
//      scheme 0                          -- a legacy opaque counter: the whole value is one number that
//                                           the app author bumped by hand, with no digit structure at all
//
//The scheme byte exists because packs built before this convention are already installed on cubes in the
//field, and they carry exactly such a counter -- the app template shipped "1 //v0.01" while the simulator's
//own fallback shipped "100 //v1.00", two incompatible readings of the same field. Without the tag a reader
//has to guess, and would render that 100 as "0.0.100". With it, a consumer shows a real 1.4.2 for scheme 1
//and an honest build number for scheme 0. Nothing on the wire changes: the field was, and stays, 4 bytes.
//
//Deliberately dependency-free (just <stdint.h>): oct_pack.h itself drags in the whole pack runtime
//(FreeRTOS types via oct_vars.h -> oct_types.h) and is explicitly warned against being included outside
//main.c-equivalent translation units (oct_vars.h's own header comment). Host-side tooling that only needs
//to resolve APP_VERSION -- e.g. a build-time probe that compiles a game's app.h with a real compiler
//instead of the packer's text regex -- includes this leaf header instead of oct_pack.h.
#define OCT_APP_VERSION_SEMVER  1u
#define OCT_APP_SEMVER(major, minor, patch) \
    (((uint32_t)OCT_APP_VERSION_SEMVER << 24) | (((uint32_t)(major) & 0xFFu) << 16) | (((uint32_t)(minor) & 0xFFu) << 8) | ((uint32_t)(patch) & 0xFFu))
